import os
import requests
from flask import Flask, request, redirect, url_for, session

app = Flask(__name__)
app.secret_key = os.urandom(24)

# Auth0 domain and client details
AUTH0_DOMAIN = os.environ.get("AUTH0_DOMAIN")
AUTH0_CLIENT_ID = os.environ.get("AUTH0_CLIENT_ID")
AUTH0_CLIENT_SECRET = os.environ.get("AUTH0_CLIENT_SECRET")
AUTH0_CALLBACK_URL = os.environ.get("AUTH0_CALLBACK_URL", "http://localhost:5000/callback")

@app.route("/")
def index():
    if "user" in session:
        return f"Hello, {session['user']['name']}! <a href='/logout'>Logout</a>"
    else:
        auth_url = (
            f"https://{AUTH0_DOMAIN}/authorize?"
            f"response_type=code&"
            f"client_id={AUTH0_CLIENT_ID}&"
            f"redirect_uri={AUTH0_CALLBACK_URL}&"
            f"scope=openid profile email"
        )
        return f'<a href="{auth_url}">Login with Auth0</a>'

@app.route("/callback")
def callback_handling():
    code = request.args.get("code")
    if not code:
        return "Error: No authorization code received", 400

    token_url = f"https://{AUTH0_DOMAIN}/oauth/token"
    token_payload = {
        "grant_type": "authorization_code",
        "client_id": AUTH0_CLIENT_ID,
        "client_secret": AUTH0_CLIENT_SECRET,
        "code": code,
        "redirect_uri": AUTH0_CALLBACK_URL,
    }

    try:
        response = requests.post(token_url, json=token_payload)
        response.raise_for_status()  # Raise an exception for HTTP errors
        token_info = response.json()

        access_token = token_info.get("access_token")
        id_token = token_info.get("id_token")

        if not access_token or not id_token:
            return "Error: Did not receive expected tokens", 500

        # Optionally, fetch user profile using the access token
        userinfo_url = f"https://{AUTH0_DOMAIN}/userinfo"
        userinfo_headers = {"Authorization": f"Bearer {access_token}"}
        userinfo_response = requests.get(userinfo_url, headers=userinfo_headers)
        userinfo_response.raise_for_status()
        user_profile = userinfo_response.json()

        session["user"] = {
            "name": user_profile.get("name", user_profile.get("email", "User")),
            "email": user_profile.get("email"),
            "sub": user_profile.get("sub"),
            "access_token": access_token,
        }
        return redirect(url_for("index"))

    except requests.exceptions.RequestException as e:
        return f"Error exchanging code for tokens: {e}", 500

@app.route("/logout")
def logout():
    session.pop("user", None)
    # Redirect to Auth0's logout endpoint
    logout_url = (
        f"https://{AUTH0_DOMAIN}/v2/logout?"
        f"client_id={AUTH0_CLIENT_ID}&"
        f"returnTo={url_for('index', _external=True)}"
    )
    return redirect(logout_url)

if __name__ == "__main__":
    # Ensure environment variables are set for a real application
    # For local testing, you might need to set these manually or use a .env file
    if not all([AUTH0_DOMAIN, AUTH0_CLIENT_ID, AUTH0_CLIENT_SECRET]):
        print("Please set AUTH0_DOMAIN, AUTH0_CLIENT_ID, and AUTH0_CLIENT_SECRET environment variables.")
        exit(1)
    app.run(debug=True)
